     for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
      Y,X=y+dy,x+dx
      if 0<=Y<H and 0<=X<W and m[Y,X] and not seen[Y,X]:seen[Y,X]=1;q.append((Y,X))
    if len(pts)>3:
     a=np.array(pts); comps.append((len(pts),(round(a[:,1].mean()+118,1),round(a[:,0].mean()+120,1)),(a[:,1].min()+118,a[:,0].min()+120,a[:,1].max()+118,a[:,0].max()+120)))
 print(name,sorted(comps,reverse=True))
